using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MysticalMagnetOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/MysticalMagnetOmenData")]
public class MysticalMagnetOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.MysticalMagnetOmenData = delegate(Dice dice)
		{
			if ((dice as PlayerDice).Character == ReferenceSingleton<AssetsReference>.Instance.Any)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ModifyGold(ActionValue);
				ReferenceSingleton<AssetsReference>.Instance.SaveSystem.SaveGold(saveAndStoreCache: true);
			}
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.MysticalMagnetOmenData = null;
	}
}
